package run.ikaros.game; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/v2/games") public class GameArchiveController{private final GameArchiveService service;public GameArchiveController(GameArchiveService s){service=s;}@PostMapping public Mono<GameView> game(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@Valid@RequestBody CreateGameRequest r){return service.createGame(o,r);}@GetMapping public Flux<GameView> games(@RequestHeader("X-Ikaros-Actor-Id")UUID o){return service.games(o);}@PostMapping("/platforms")public Mono<GamePlatformView> platform(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@Valid@RequestBody CreateGamePlatformRequest r){return service.createPlatform(o,r);}@GetMapping("/platforms")public Flux<GamePlatformView> platforms(@RequestHeader("X-Ikaros-Actor-Id")UUID o){return service.platforms(o);}@PostMapping("/{gameId}/versions")public Mono<GameVersionView> version(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID gameId,@Valid@RequestBody CreateGameVersionRequest r){return service.createVersion(o,gameId,r);}@GetMapping("/{gameId}/versions")public Flux<GameVersionView> versions(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID gameId){return service.versions(o,gameId);}@PostMapping("/{gameId}/assets")public Mono<GameAssetView> asset(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID gameId,@Valid@RequestBody CreateGameAssetRequest r){return service.addAsset(o,gameId,r);}@GetMapping("/{gameId}/assets")public Flux<GameAssetView> assets(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID gameId){return service.assets(o,gameId);}@PostMapping("/assets/{assetId}/actions/availability")public Mono<GameAssetView> availability(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID assetId,@Valid@RequestBody UpdateGameAssetAvailabilityRequest r){return service.availability(o,assetId,r);}}
